# -*- coding: utf-8 -*-
"""Polity handwritten notes, chapters 80-87 (full version). Source: Sarrthi IAS GS-2 Polity 'Constitutional Bodies and Statutory Bodies'."""
from dsl import *
from hwlib import P, H, R
OWN = lambda w, t: mn(w, t + ' <i>(own mnemonic)</i>')
NOPYQ = 'None quoted in the handout · Constitutional and Statutory Bodies handout '

CHS = [
dict(toc='NCSC and NCST: Articles 338 and 338A, functions, achievements, critique', id=80, title='NCSC AND NCST · ARTICLES 338, 338A · FUNCTIONS · ACHIEVEMENTS · CRITIQUE · REFORMS', part=0, icon='people', prio='L',
 pyq=NOPYQ + 'pp. 3-8',
 simple='The National Commission for Scheduled Castes (Article 338) and the National Commission for Scheduled Tribes (Article 338A) are constitutional watchdogs. They check whether the safeguards given to SCs and STs are really working, inquire into complaints and advise the government on development. They can summon people and documents like a civil court, but they can only recommend, not order. Delays, vacancies, weak independence and thin staff reduce their impact.',
 nodes=[
 sec('NATIONAL COMMISSION FOR SCHEDULED CASTES (NCSC): THE BASICS', 'b'),
 tb(['Article', 'What it does'],
    ['<b>338</b>', 'Creates the NCSC and lays down its composition, powers and functions. Because it sits in the Constitution, it is a constitutional body, not a mere statutory one.'],
    ['<b>341</b>', 'The President, after consulting the Governor of the State concerned, specifies which castes are to be treated as Scheduled Castes in that State or Union Territory. A caste is therefore an SC only through this notification.'],
    ['<b>366(24)</b>', 'Defines “Scheduled Castes” for constitutional purposes (the castes, races or tribes, or parts of them, that are notified under Article 341).']),
 t('<b>Functions: what the NCSC actually does</b>',
   '<b>1. Investigation and monitoring.</b> It examines the constitutional and legal safeguards meant for SCs, evaluates how well they work and points out where implementation is failing. Example: reviewing reservation in education, jobs and promotions in central and State services.',
   '<b>2. Inquiry into complaints.</b> It looks into cases where SCs are denied their rights, face atrocities or are discriminated against, and recommends remedies. Example: violence against Dalits that falls under the SC/ST (Prevention of Atrocities) Act.',
   '<b>3. Advice on development planning.</b> It takes part in, and advises on, the planning of socio-economic development for SCs so that policy is inclusive. Example: inputs on targeted schemes like the Scheduled Castes Sub-Plan.',
   '<b>4. Annual and special reports.</b> It reports to the President on how the safeguards are being implemented and on the SCs’ socio-economic progress.',
   '<b>5. Recommendations to governments.</b> It suggests policy measures so that safeguards, welfare schemes and development programmes are implemented effectively.',
   '<b>6. Extra role.</b> It also performs similar functions for the Anglo-Indian community. Until the <b>102nd Constitutional Amendment Act, 2018</b> the NCSC also handled matters relating to OBCs; that work now belongs to the NCBC.'),
 sec('NCSC: AN ANALYTICAL LOOK', 'r'),
 t('<b>Where the NCSC has worked (strengths)</b>',
   '<b>Service safeguards.</b> It has scrutinised recruitment, promotion and reservation practices across government services. It encouraged SC/ST employee associations, liaison officers and special grievance cells in ministries and PSUs to deal with discrimination. It has intervened where reservation benefits were denied in central universities and UPSC recruitment.',
   '<b>Education.</b> It focuses on literacy and access to higher education, with special attention to female literacy. It monitors scholarships and pushes for better schools and hostels for SC students. Its review of the Post-Matric Scholarship Scheme found poor disbursement of funds and recommended Direct Benefit Transfer (DBT).',
   '<b>Atrocities and civil rights.</b> It monitors atrocity cases, especially custodial violence and police excesses. NCRB data for 2021 shows crimes against SCs make up nearly <b>89%</b> of all atrocity cases against SCs and STs combined, which shows the scale of the problem. However, it tracks numbers and procedures more than it pushes wider social reform.',
   '<b>Land and economic issues.</b> It recognises that SCs depend heavily on agriculture and argues for land reform and protection against land alienation. Its proposals on redistribution and tenancy rights usually meet political resistance. Land disputes in Tamil Nadu and Bihar show that Dalits remain vulnerable to land grabbing.'),
 t('<b>Where it falls short (limitations)</b>',
   '<b>Non-binding recommendations:</b> despite civil-court-like investigative powers, its findings have no legal force, so governments can ignore them.',
   '<b>Procedural delay:</b> inquiries drag on, so justice becomes slow and often ineffective.',
   '<b>Perceived closeness to government:</b> appointments and alignment with government positions raise doubts about its independence.',
   '<b>Late reports:</b> annual reports arrive late and are often not discussed in Parliament. The 12th Report (for 2018-20) was tabled only in 2022.',
   '<b>Elite bias:</b> priorities tend to favour better-off SC groups, while the poorest Dalits are under-represented.',
   '<b>Reactive style:</b> it rarely uses its suo motu power to start action on its own.'),
 t('<b>Reforms suggested</b>',
   '<b>Autonomy:</b> appoint members through a bipartisan process so the executive cannot control them.',
   '<b>Timely reporting:</b> make annual submission and discussion in Parliament mandatory for accountability.',
   '<b>Inclusion:</b> concentrate on the most marginalised sub-groups inside the SC category rather than letting a few groups capture benefits.',
   '<b>Data-driven work:</b> use qualitative and quantitative studies and involve social scientists in policy advice.',
   '<b>Clear roles:</b> sort out overlaps with the Ministry of Social Justice.',
   '<b>Proactive role:</b> use suo motu powers in atrocities, land disputes and denial of reservation.'),
 bx('gr', '<b>Concluding thought:</b> caste identities are slowly weakening in cities because of education and mobility, but caste inequality persists, especially in rural India. Leaders such as B. R. Ambedkar, K. R. Narayanan and Ram Nath Kovind show progress, yet they also show why institutional safeguards are still needed. The NCSC has to change from a procedural watchdog into a proactive reformist body.'),
 sec('NATIONAL COMMISSION FOR SCHEDULED TRIBES (NCST): BACKGROUND', 'b'),
 t('<b>Who is a “Scheduled Tribe”?</b>',
   'A “tribe” generally means a community with shared culture, language and territory, often living in relative isolation. A <b>Scheduled Tribe (ST)</b> is a constitutional category: communities <b>notified under Article 342</b> for special protection.',
   'The Constitution neither defines “tribe” nor gives criteria for inclusion. Tribal communities are recognised by distinct cultural traditions, remoteness and socio-economic disadvantage.',
   '<b>Census 2011:</b> India has <b>10.42 crore STs, about 8.6%</b> of the population. They live on over <b>15% of the country’s area</b> and sit on nearly <b>20% of natural resources</b>.',
   'They are concentrated in Central India (Madhya Pradesh, Chhattisgarh, Jharkhand, Odisha, Gujarat, Maharashtra, Rajasthan) and the North-East.',
   'Development levels vary widely: Mizoram has near-universal literacy, while groups such as the <b>Jarawas and Shompens</b> of the Andaman and Nicobar Islands are highly vulnerable.',
   'The NCST is created under <b>Article 338A</b> (inserted when the single SC/ST commission was split).'),
 t('<b>Functions of the NCST</b>',
   '<b>1. Investigation.</b> Examines how constitutional and legal safeguards for STs are implemented. Example: monitoring the PESA Act in Scheduled Areas.',
   '<b>2. Complaint redressal.</b> Inquires into specific complaints of denial of rights or discrimination. Example: land alienation disputes in Jharkhand and Odisha.',
   '<b>3. Planning advice.</b> Gives inputs on socio-economic policy, evaluates schemes and suggests reforms. Example: recommending focus on tribal education and livelihood under the Tribal Sub-Plan.',
   '<b>4. Reporting.</b> Submits annual and special reports to the President on tribal rights and welfare.',
   '<b>5. Policy recommendations.</b> Advises the Union and States on protection, welfare and development of STs.'),
 t('<b>Additional functions under the 2005 Rules</b>',
   'Securing the rights of tribals over <b>minor forest produce</b>.',
   'Protecting tribal ownership over land, water and mineral resources.',
   'Making sure tribals <b>displaced by development projects</b> are rehabilitated.',
   'Preventing land alienation and helping restore land that has already been alienated.',
   'Promoting tribal participation in forest management and social afforestation.',
   'Helping implement <b>PESA, 1996</b> in Scheduled Areas.',
   'Encouraging a shift from <b>jhum (shifting) cultivation</b> to sustainable livelihoods.'),
 sec('NCST: ACHIEVEMENTS AND CRITIQUE', 'r'),
 tb(['Achievement', 'What happened'],
    ['<b>Land safeguards (2023)</b>', 'Issued a notice over the Great Nicobar project, questioning the diversion of <b>84.1 sq km</b> of tribal reserve land and <b>130 sq km</b> of forest land without proper consultation.'],
    ['<b>Forest rights</b>', 'Its opposition to the <b>2019 amendments to the Forest Rights Act (FRA)</b> helped stall proposals that would have diluted community rights over forests.'],
    ['<b>Displacement oversight (2017)</b>', 'A Special Report showed that <b>28%</b> of displaced tribal households in Chhattisgarh mining projects had not been rehabilitated, which led the government to review.'],
    ['<b>Education advice (2020)</b>', 'Its input on Eklavya Model Residential Schools pushed for expansion to <b>452 new schools</b> in under-served tribal belts.'],
    ['<b>Complaint redressal</b>', 'Using civil-court powers it summoned State officials in the <b>Pathalgadi</b> cases (Jharkhand, 2016), which brought national attention to the misuse of sedition-type laws against tribals.'],
    ['<b>Reservation monitoring</b>', 'The 2018-19 Annual Report recorded a <b>4.5% shortfall</b> in ST representation in central PSU jobs and pushed ministries to correct it.']),
 t('<b>Critique and limitations</b>',
   '<b>Dysfunction:</b> parliamentary reports show the NCST has been largely inactive for about four years and has not submitted reports to Parliament, which undermines its mandate of monitoring safeguards.',
   '<b>Weak regional reach:</b> it works with only <b>six regional offices</b>, many understaffed. Requests for offices in tribal-heavy States such as Andhra Pradesh and Maharashtra remain unmet.',
   '<b>Lack of independence:</b> the Ministry of Tribal Affairs overshadows it, which blurs the line between an advisory commission and an executive department.',
   '<b>Exclusion from policy-making:</b> it has complained of inadequate consultation on key laws such as the Forest Rights Act, which directly affect tribal welfare.',
   '<b>Underfunding:</b> chronic budget shortages limit inquiries, outreach and monitoring, and reduce operational independence. A 2022 parliamentary committee noted it was working with <b>under 50% of sanctioned strength</b>.'),
 t('<b>Way forward for the NCST</b>',
   '<b>Fill vacancies quickly</b> so a fully functional body with expert members restores credibility and timely monitoring.',
   '<b>Expand regional presence</b> with more, properly staffed offices, so it can talk to tribal communities directly.',
   '<b>Reinforce autonomy</b> from the Ministry of Tribal Affairs through structural reform, so it acts as a neutral protector.',
   '<b>Formal consultation:</b> make it mandatory to consult the Commission on policies that affect STs, so tribal voices are built into law-making.',
   '<b>Better budget</b> and financial autonomy for investigations, outreach and monitoring.'),
 bx('gr', '<b>Concluding thought:</b> the NCST was meant to be the guardian of tribal rights under Article 338A. Staff shortages, limited independence, weak outreach and poor funding have blunted it. Its effectiveness depends on timely reporting, government responsiveness and proactive suo motu action, especially because tribals are over 8% of the population and still face marginalisation.'),
 ],
 recall=[('NCSC is under which Article?', 'Article 338'), ('NCST is under which Article?', 'Article 338A'), ('Who specifies the SCs of a State?', 'The President, after consulting the Governor (Art 341)'), ('Under which Article are STs notified?', 'Article 342'), ('Until when did the NCSC also handle OBC matters?', 'Until the 102nd Amendment Act, 2018'), ('STs in Census 2011', '10.42 crore, 8.6% of the population'), ('NCST regional offices', 'Six, many understaffed'), ('NCSC 12th Report (2018-20) tabled in', '2022 (late)'), ('Which law did NCST help protect in 2019?', 'Forest Rights Act, by opposing its amendments')]),

dict(toc='NCBC, OBC sub-categorisation (Rohini), challenges of SC/ST/OBC commissions, types of rights', id=81, title='NCBC · ROHINI COMMISSION · CHALLENGES OF SC-ST-OBC COMMISSIONS · TYPES OF RIGHTS', part=0, icon='people', prio='L',
 pyq=NOPYQ + 'pp. 8-11',
 simple='The NCBC got constitutional status in 2018, so it can no longer be changed at the executive’s will and it has civil-court powers in inquiries. All three commissions (SC, ST, OBC) suffer from similar problems: vacancies, advisory-only powers, delays and low awareness. The chapter also explains the four kinds of rights (natural, moral, legal, human) and how Fundamental Rights differ from other constitutional rights.',
 nodes=[
 sec('NATIONAL COMMISSION FOR BACKWARD CLASSES (NCBC)', 'b'),
 t('<b>Why backwardness is a caste question in India</b>',
   'Backward classes in India are rooted in systemic disadvantage tied to <b>caste, occupation and social hierarchy</b>.',
   'Social “class” is fluid (a person can move up), but caste-based backwardness carries <b>intergenerational barriers</b> in education, jobs and representation.',
   'To address this, constitutional and statutory mechanisms were created. They ended in the NCBC.',
   'Once the NCBC was given <b>constitutional status (2018)</b>, it no longer depends on executive discretion. It works as an autonomous constitutional body, giving it autonomy while keeping it accountable to the highest constitutional office.'),
 t('<b>Justice Rohini Commission (OBC sub-categorisation)</b>',
   'Set up in <b>2017 under Article 340</b> to examine sub-classification of the <b>27% OBC quota</b>.',
   'It proposed dividing OBC castes into <b>four groups</b> so that benefits reach the less-advantaged castes, not only the dominant ones.',
   '<b>Proposed split:</b> Group 1 gets 2%, Group 2 gets 6%, Group 3 gets 9% and Group 4 gets 10% (total 27%).',
   'The final report was still awaited as per the handout.'),
 t('<b>Powers of the NCBC (civil-court powers)</b>',
   'It can <b>summon and enforce the attendance</b> of any person from anywhere in India and examine them on oath.',
   'It can require the <b>discovery and production</b> of official or private documents.',
   'It can receive evidence on <b>affidavits</b> and requisition public records from courts or government offices.',
   'It can issue summons for witnesses and documents, and has any other powers the President gives it.',
   'These quasi-judicial powers let it investigate independently and hold institutions accountable.'),
 t('<b>Benefits of constitutional status (with examples)</b>',
   '<b>1. More authority.</b> Civil-court powers in inquiries make officials accountable. It can summon officers, demand records and take affidavits while probing OBC grievances.',
   '<b>2. Wider mandate.</b> Earlier it only revised the OBC list; now it also monitors welfare schemes and safeguards. It can probe denial of scholarships or weak enforcement of reservation.',
   '<b>3. Parliamentary oversight.</b> Its reports are tabled in Parliament, which forces an executive response. Its 2022 report on under-use of OBC welfare funds made ministries explain corrective steps.',
   '<b>4. Independence.</b> Tenure and service safeguards stop arbitrary changes to how it works.',
   '<b>5. Stronger social-justice role.</b> It acted on the reservation backlog in central PSUs and pushed recruitment drives for OBC candidates.',
   '<b>6. Symbolic and political value.</b> Constitutional status in 2018 reassured the roughly <b>40%</b> of India that is OBC of the State’s commitment to equity.'),
 bx('ye', '<b>Note on the handout:</b> the table on the NCBC’s composition and Articles (338B and related provisions) was an image in the PDF and could not be read. Add it from the handout by hand.'),
 sec('CHALLENGES FACED BY SC, ST AND OBC COMMISSIONS', 'r'),
 t('<b>Seven shared problems</b>',
   '<b>1. Vacancies and resource gaps.</b> Persistent understaffing and small budgets weaken them. A 2022 Parliamentary Committee noted the NCST was running on less than 50% of sanctioned strength, which hurt its inquiries.',
   '<b>2. Erosion of autonomy.</b> Politics influences appointments and recommendations are not binding, which reduces credibility. NCBC’s 2020 reports on OBC reservation backlog in central universities were ignored by ministries.',
   '<b>3. Weak statutory powers.</b> They cannot enforce compliance or fix structural problems. The NCBC cannot define “backwardness”, as clarified in the Maratha Quota judgment (2021).',
   '<b>4. Case backlog and delayed reporting.</b> Thousands of complaints are pending and annual reports reach Parliament late, which blunts accountability.',
   '<b>5. Opaque functioning.</b> Little transparency in how members are selected and limited disclosure of outcomes lower public trust.',
   '<b>6. Representation deficit.</b> Retired bureaucrats dominate instead of experts, academics or community representatives, so perspectives are narrow.',
   '<b>7. Low outreach and awareness.</b> Target communities often do not know how to complain. NCRB 2020 showed rising SC/ST atrocity cases but few complaints reached the commissions because people did not know the procedure.'),
 t('<b>Pathways for reform</b>',
   '<b>Independence:</b> redo appointment processes with clear criteria, expert representation and less political interference.',
   '<b>Wider powers:</b> consider making recommendations binding; let the NCBC define backwardness parameters; harmonise powers across the SC, ST and OBC commissions.',
   '<b>Efficiency:</b> fill vacancies quickly, give adequate budgets and modernise case-handling infrastructure.',
   '<b>Transparency:</b> digital case tracking, fixed timelines for resolving complaints and regular public disclosures.',
   '<b>Data and research:</b> build full caste/tribe databases and commission impact studies of welfare schemes (like post-NFHS style surveys).',
   '<b>Collaboration:</b> structured coordination with ministries, State commissions and NGOs, and partnerships with academic institutions.',
   '<b>Capacity:</b> a dedicated cadre for these commissions, with training for members and staff in rights, technology and emerging challenges.'),
 bx('gr', '<b>Conclusion:</b> strengthening the SC, ST and OBC commissions needs autonomy, resources and binding powers. With transparency, data-driven policy and collaboration, they can become credible constitutional watchdogs that deliver substantive equality.'),
 sec('TYPES OF RIGHTS', 'b'),
 t('<b>What is a right?</b> A justified claim that allows individuals to live with dignity and freedom. Rights are broadly of four types.'),
 tb(['Type', 'Meaning and key features', 'Examples'],
    ['<b>Natural rights</b>', 'Belong to every person by birth. They are <b>not granted by the government</b>. Considered universal and inalienable.', 'Right to life, liberty and property'],
    ['<b>Moral rights</b>', 'Based on moral values, conscience and social acceptance. Generally <b>not legally enforceable</b>.', 'Right to respectful and fair treatment'],
    ['<b>Legal rights</b>', 'Recognised and protected by law and <b>enforceable through courts</b>.', 'Civil rights (life, liberty, equality); Political rights (voting, contesting elections); Economic rights (work, fair wages, social security)'],
    ['<b>Human rights</b>', 'Universal and inalienable rights available to all individuals: civil, political, economic, social and cultural. Recognised under the <b>UDHR, 1948</b>.', 'Right to life, dignity, equality, education and freedom']),
 sec('FUNDAMENTAL RIGHTS vs CONSTITUTIONAL RIGHTS', 'r'),
 t('Both are categories of <b>legal rights</b>. The difference is where they sit and how they are enforced.'),
 tb(['Basis', 'Fundamental Rights', 'Other constitutional rights'],
    ['Meaning', 'Basic rights guaranteed under <b>Part III</b> of the Constitution', 'Rights given by the Constitution but <b>outside Part III</b>'],
    ['Provisions', 'Articles 12-35', 'Various provisions, such as Article 300A and Article 326'],
    ['Examples', 'Right to Equality, Freedom, Life and Personal Liberty', 'Right to Property (Art 300A) and Right to Vote (Art 326)'],
    ['Enforcement', 'Directly enforceable through <b>Article 32 (Supreme Court)</b> and <b>Article 226 (High Court)</b>', 'Enforceable through appropriate legal remedies, depending on the right']),
 bx('pk', '<b>Key point:</b> all Fundamental Rights are constitutional rights, but not all constitutional rights are Fundamental Rights.'),
 ],
 recall=[('When did the NCBC get constitutional status?', '2018 (102nd Amendment)'), ('Under which Article was the Rohini Commission set up?', 'Article 340, in 2017'), ('Rohini proposal for the 27% OBC quota', '4 groups: 2%, 6%, 9%, 10%'), ('Which judgment said NCBC cannot define backwardness?', 'Maratha Quota judgment, 2021'), ('Four types of rights', 'Natural, moral, legal, human'), ('Which rights can be enforced directly under Art 32?', 'Fundamental Rights (Part III)'), ('Right to property is under which Article now?', 'Article 300A (a constitutional right, not fundamental)'), ('Right to vote is under which Article?', 'Article 326')]),

dict(toc='NHRC: composition, working, functions, role, challenges, failures, reforms', id=82, title='NATIONAL HUMAN RIGHTS COMMISSION (NHRC) · COMPOSITION · WORKING · FUNCTIONS · ROLE · REFORMS', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 11-16',
 simple='The NHRC was set up in 1993 under the Protection of Human Rights Act after worries about custodial violence and encounter deaths. It inquires into violations (suo motu or on complaint), visits jails, reviews safeguards and spreads awareness. Its recommendations are only advisory, it cannot touch the armed forces except to ask for reports, and GANHRI has criticised its independence. Reforms aim to give it binding force, transparent appointments and more staff.',
 nodes=[
 sec('WHY AND HOW THE NHRC WAS CREATED', 'b'),
 t('<b>Background</b>',
   'Human rights are the inherent and inalienable rights of every person, ensuring dignity, equality and freedom regardless of race, caste, gender or belief.',
   'In the 1980s and early 1990s, concern about <b>custodial violence, encounter deaths and systemic discrimination</b> pushed India to build an institution to protect rights. This led to the NHRC under the <b>Protection of Human Rights Act, 1993</b>.',
   'Parliament built a <b>three-tier structure</b>: the NHRC at the national level, <b>State Human Rights Commissions (SHRCs)</b> in States, and <b>Human Rights Courts</b> in districts. This aims for both accountability and access.',
   'It works in line with the UN-endorsed <b>Paris Principles (1993)</b>, which call for autonomy, independence and accountability of national human rights institutions.'),
 sec('COMPOSITION AND STRUCTURE', 'r'),
 tb(['Aspect', 'Details'],
    ['Established', '<b>12 October 1993</b>, under the Protection of Human Rights Act, 1993'],
    ['Composition', 'A Chairperson, <b>5 full-time Members</b> and <b>7 ex-officio Members</b>'],
    ['Selection committee', 'Prime Minister (chair); Home Minister; Speaker of Lok Sabha; Deputy Chairman of Rajya Sabha; Leader of Opposition in Lok Sabha; Leader of Opposition in Rajya Sabha'],
    ['Appointing authority', 'The <b>President of India</b>'],
    ['Eligibility: Chairperson', 'A retired Chief Justice of India or a retired Judge of the Supreme Court'],
    ['Eligibility: Members', 'One Member who is or was a Supreme Court Judge; one who is or was a <b>Chief Justice of a High Court</b>; <b>three</b> with knowledge or experience of human rights (at least one must be a woman)'],
    ['Ex-officio Members', 'Chairpersons of the National Commissions for SCs, STs, Women and Minorities; Chairperson of the National Commission for Backward Classes; Chairperson of the NCPCR; Chief Commissioner for Persons with Disabilities'],
    ['Term', '<b>3 years or until age 70</b>, whichever is earlier. Eligible for reappointment.'],
    ['Removal', 'By the President on grounds of misbehaviour or incapacity, <b>after an inquiry by the Supreme Court</b>'],
    ['Salary and allowances', 'Fixed by the Central Government but <b>cannot be changed to their disadvantage</b>'],
    ['Powers', 'Powers of a civil court during inquiries; can call for information from government and authorities; can recommend compensation or prosecution; can use the services of officers and investigation agencies; expanded role in Union Territories, and the Secretary-General has administrative and financial powers']),
 OWN('PM-HM-LS-DCh-LoP', 'NHRC selection panel = <b>PM, Home Minister, Speaker, RS Deputy Chairman, and the two Leaders of Opposition</b> (six people).'),
 sec('HOW THE NHRC WORKS (PROCEDURE)', 'g'),
 t('<b>Step by step</b> (governed by the 1993 Act and the NHRC (Procedure) Regulations, 1994)',
   '<b>1. Complaint.</b> Individuals, NGOs or the Commission itself (suo motu) can start a case. It should generally relate to violations within <b>one year</b> of occurrence. The Law Division first screens it before it is admitted.',
   '<b>2. Inquiry.</b> After admission the NHRC can either investigate itself through its <b>Investigation Division</b> (headed by an officer of Director General of Police rank) or ask the concerned authority or police for a report. It then decides whether the act is a “violation” under the law.',
   '<b>3. Hearings and recommendations.</b> In serious matters (custodial deaths, bonded labour, encounter killings) it holds open hearings or field visits. It then recommends compensation, disciplinary action or a policy change.',
   '<b>4. Follow-up.</b> The ministry or State must submit an <b>Action Taken Report (ATR) within one month</b>. The NHRC reviews compliance and may publish non-compliance in its annual report, which is tabled in Parliament, so there is public accountability.',
   '<b>5. Coordination and research.</b> It works through specialised divisions (Research, Training, Policy, Awareness) to build institutional knowledge.'),
 sec('FUNCTIONS (SECTION 12 OF THE 1993 ACT)', 'b'),
 t('<b>Eleven functions</b>',
   '<b>1. Inquiry into violations</b> (Sections 17-18): into violations, or negligence in preventing them, by a public servant, suo motu, on a petition, or on a court’s reference. This is its core function.',
   '<b>2. Intervening in court proceedings</b> that involve allegations of human rights violations, with the court’s approval.',
   '<b>3. Inspecting detention centres</b> (jails, juvenile homes, psychiatric facilities) to study living conditions and suggest reform, in line with the UN <b>Mandela Rules (2015)</b>.',
   '<b>4. Reviewing legal safeguards</b>: Fundamental Rights, criminal procedure, prison laws and police manuals, and advising on effective enforcement.',
   '<b>5. Addressing factors that inhibit rights</b>: terrorism, displacement, communal violence, environmental damage; suggesting preventive or remedial steps.',
   '<b>6. International alignment</b>: studying treaties like the <b>UDHR 1948, ICCPR 1966 and CEDAW 1979</b> and recommending domestic alignment; coordinating with the UN Human Rights Council and other national institutions under the Paris Principles.',
   '<b>7. Research and policy</b> on themes like gender violence, bonded labour and climate justice.',
   '<b>8. Human rights literacy</b>: publications, training for police and officials, campaigns in schools and universities with NCERT and UGC.',
   '<b>9. Working with civil society</b>: supporting NGOs and rights defenders as partners in advocacy and victim assistance.',
   '<b>10. Miscellaneous</b>: any other function needed for promoting rights, including setting up human rights courts, monitoring bonded labour and overseeing women and child protection.',
   '<b>11. Added by practice and amendment</b>: monitoring Supreme Court orders on custodial deaths, manual scavenging and police reforms, and overseeing the National Action Plan on Business and Human Rights (NAP-BHR) started by the Ministry of Corporate Affairs.'),
 bx('ye', '<b>GANHRI (Global Alliance of National Human Rights Institutions)</b> accredits national human rights bodies. It has repeatedly raised concerns about India’s NHRC. Recent reports (2024-25) say the selection process is <b>non-transparent</b> (vacancies not publicly advertised; vague application, screening and appointment procedures), follow-up on serious violations is weak, independence from the executive is limited and civil society participation is thin. These critiques contributed to the recommendation to <b>downgrade the NHRC from “A” grade</b> accreditation. <i>(verify current status)</i>'),
 sec('ROLE PLAYED BY THE NHRC', 'r'),
 t('<b>Main contributions</b>',
   '<b>Guidelines and legal oversight.</b> It issued detailed guidelines on custodial deaths, which later shaped Supreme Court law (<b>D. K. Basu v. State of West Bengal, 1997</b>). It criticised misuse of special security laws such as POTA and TADA and recommended safeguards against arbitrary detention.',
   '<b>Socio-economic rights and marginalised groups.</b> It took up the starvation deaths in Odisha (2001-02), leading to stronger monitoring of food-security schemes in Kalahandi and Bolangir. In 2022 it flagged large-scale displacement of tribals in Chhattisgarh due to mining and told the State to ensure rehabilitation.',
   '<b>Complementing the judiciary.</b> In <b>NHRC v. State of Arunachal Pradesh (1996)</b> the Supreme Court upheld the NHRC’s standing to move the court to protect Chakma refugees. Its prison reports (2017-18) fed into the <b>Justice Amitava Roy Committee</b> recommendations on decongesting prisons.',
   '<b>Policy advocacy and awareness.</b> Its recommendations helped shape the <b>Juvenile Justice Act (2000)</b> and the <b>Mental Healthcare Act (2017)</b>. It launched open online courses on human rights in 2020.'),
 tb(['Case (year)', 'NHRC’s role'],
    ['Gujarat riots (2002)', 'Took suo motu notice of mass graves, pressed the State to report on measures and moved the Supreme Court on behalf of victims'],
    ['Punjab mass cremations (1995-2012)', 'Directed <b>Rs 1.75 lakh</b> compensation each to <b>1,051 families</b> whose kin were cremated unlawfully; a landmark for dignity rights'],
    ['Silicosis deaths in Gujarat (2011-ongoing)', 'Investigated unsafe working conditions for tribal labourers; pressed for State action and compensation'],
    ['Rohingya refugees in Jammu (2017)', 'Asked the government to ensure basic humanitarian facilities and non-discriminatory treatment'],
    ['Farmers’ suicides in Maharashtra (2018)', 'Issued notices to the State over agrarian distress and the lack of institutional support for farmers’ families'],
    ['Manipur extra-judicial killings (2013-16)', 'After petitions, monitored the SC-appointed SIT on <b>1,528</b> alleged fake encounters; it also showed NHRC’s limits, with the SC calling it a “<b>toothless tiger</b>”'],
    ['COVID-19 migrant crisis (2020)', 'Intervened in migrant deaths from hunger or exhaustion; sought reports from States and railways; pressed for relief'],
    ['Hathras case (2020)', 'Took cognisance of the alleged gang-rape of a Dalit woman and the hurried cremation; sought accountability of UP authorities'],
    ['Manipur violence (2023)', 'Issued notices to the Centre and State on large-scale displacement and sexual violence against women during ethnic clashes']),
 sec('CHALLENGES AND WHERE THE NHRC HAS FAILED', 'r'),
 t('<b>Six challenges</b>',
   '<b>1. No enforcement power.</b> Recommendations are advisory, so compliance is poor. It cannot impose penalties or directly award compensation. In 2016, then NHRC Chairperson Justice H. L. Dattu himself called it a “toothless tiger” in an interview.',
   '<b>2. Limited jurisdiction.</b> In cases involving the armed forces it can only seek a report from the government. It cannot take up cases older than one year, or violations by private individuals unless State complicity is proved.',
   '<b>3. Structure and composition.</b> Too many retired judges make it more judicial than human-rights-centred. There is limited diversity: SCs, STs, women and civil society activists are under-represented. Critics call it a “post-retirement” home for judges and bureaucrats.',
   '<b>4. Operations and resources.</b> A heavy backlog from excess caseload; inadequate staffing, especially in investigation and research (many on deputation); scarce funds that hamper outreach, especially at State level.',
   '<b>5. Independence and credibility.</b> The executive dominates appointments, raising doubts about impartiality; reliance on government resources reduces perceived autonomy. GANHRI downgraded its accreditation in 2017, citing political interference and lack of pluralism.',
   '<b>6. Accessibility and awareness.</b> Many citizens, especially from marginalised groups, do not know the NHRC’s mandate. Procedural complexity and urban-centred working limit access.'),
 tb(['Case (year)', 'What went wrong'],
    ['G. N. Saibaba case (2024-25)', 'Despite repeated pleas from the imprisoned academic about prison conditions and health, the NHRC was criticised for dismissing complaints and not ensuring protection and medical care'],
    ['“Nata Pratha” minor girl suicide case (2024)', 'The girl, allegedly sold by her father after police ignored her complaint, died by suicide in 2020. The NHRC enquiry found police inaction, but justice has been slow and accountability partial'],
    ['District Mineral Foundation (DMF) funds, Odisha (2025)', 'The NHRC asked for reports on delay or misuse of DMF funds meant for mining-affected areas, but actual corrective action and relief to affected people remain uncertain']),
 sec('WAY FORWARD: REFORMING AND STRENGTHENING THE NHRC', 'g'),
 t('<b>Six reform directions</b>',
   '<b>1. Powers and jurisdiction.</b> Make recommendations binding in grave violations, with a statutory duty on governments to respond. Extend jurisdiction to violations by private actors and security forces, with independent investigation wings.',
   '<b>2. Transparent, inclusive appointments.</b> Publicly advertise vacancies with clear application, screening and shortlisting steps. Add diversity: women, SC/ST, minorities and rights activists alongside judges.',
   '<b>3. Resources and decentralisation.</b> A dedicated budget and permanent staff instead of deputation. Regional benches and stronger SHRCs for faster handling.',
   '<b>4. Accountability and follow-up.</b> An online tracker for the status of recommendations and government responses; periodic independent audits and parliamentary review of annual reports.',
   '<b>5. Awareness and victim support.</b> Targeted outreach in rural, tribal and marginalised areas; multilingual online complaint portals; free legal and medical aid for victims.',
   '<b>6. Regular legal and institutional review.</b> Amend the Protection of Human Rights Act periodically to meet global standards like the Paris Principles; evaluate performance through external committees and civil society consultation.'),
 ],
 recall=[('NHRC established on', '12 October 1993, under the Protection of Human Rights Act, 1993'), ('NHRC members', 'Chairperson + 5 full-time + 7 ex-officio'), ('Who can be NHRC Chairperson?', 'A retired Chief Justice of India or SC judge'), ('NHRC term', '3 years or age 70, whichever is earlier'), ('Who removes an NHRC member?', 'The President, after a Supreme Court inquiry'), ('Time limit to file a complaint', 'Generally within one year of the violation'), ('ATR must be submitted within', 'One month'), ('NHRC and armed forces', 'Can only seek a report from the government'), ('International standards for national human rights bodies', 'Paris Principles (1993)'), ('Who accredits national human rights institutions?', 'GANHRI')]),

dict(toc='UDHR 1948 and the Constitution; State Human Rights Commissions; Human Rights Courts', id=83, title='UDHR 1948 AND THE CONSTITUTION · STATE HUMAN RIGHTS COMMISSIONS · HUMAN RIGHTS COURTS', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 16-19',
 simple='The UDHR (1948) set the moral base for human rights, and many of its ideas appear in India’s Preamble, Fundamental Rights, DPSP and Fundamental Duties. State Human Rights Commissions (SHRCs) are the State-level counterparts of the NHRC, and Human Rights Courts (Section 30) try human rights offences in districts. The 2019 amendment changed tenure and eligibility. Both SHRCs and these courts are weak in practice.',
 nodes=[
 sec('UNIVERSAL DECLARATION OF HUMAN RIGHTS (UDHR), 1948', 'b'),
 t('<b>What it is</b>',
   'Adopted by the UN General Assembly on <b>10 December 1948</b>. It was the <b>first international document</b> to recognise that all human beings are born free and equal in dignity and rights.',
   'Drafted after the Second World War to prevent future atrocities by setting common standards of justice, freedom and peace.',
   'It rests on four principles: <b>Dignity, Liberty, Equality and Brotherhood</b>.',
   'It has <b>30 Articles</b>, broadly grouped into civil-political rights and socio-economic rights.'),
 t('<b>How the Indian Constitution reflects the UDHR</b>',
   '<b>Preamble:</b> promises Justice, Liberty, Equality and Fraternity, reflecting the UDHR’s commitment to dignity and freedom.'),
 tb(['Indian provision', 'Matching idea', 'UDHR link'],
    ['Articles 14-18 (Fundamental Rights)', 'Equality and non-discrimination', 'UDHR Arts 1, 7'],
    ['Articles 19-22', 'Freedom, life and personal liberty', 'UDHR Arts 3, 9, 19, 20'],
    ['Articles 23-24', 'Protection against exploitation', 'UDHR Art 4'],
    ['Articles 25-28', 'Freedom of religion', 'UDHR Art 18'],
    ['Articles 29-30', 'Cultural and educational rights', 'UDHR Arts 26, 27'],
    ['Article 32', 'Constitutional remedies', 'UDHR Art 8'],
    ['DPSP: Art 38', 'Social and economic justice', 'UDHR Arts 22-25 (socio-economic rights)'],
    ['DPSP: Art 39', 'Adequate livelihood and equal pay', 'same'],
    ['DPSP: Art 41', 'Right to work, education and public assistance', 'same'],
    ['DPSP: Art 42', 'Humane working conditions and maternity relief', 'same'],
    ['DPSP: Art 47', 'Nutrition and public health', 'same'],
    ['Duty 51A(e)', 'Promote harmony; respect women’s dignity', 'UDHR emphasis on dignity'],
    ['Duty 51A(f)', 'Preserve composite culture', 'cultural rights'],
    ['Duty 51A(h)', 'Develop scientific temper and humanism', 'social responsibility']),
 t('<b>Other constitutional provisions that echo the UDHR</b>',
   '<b>Article 21A:</b> free and compulsory education for children aged 6 to 14 (UDHR Art 26).',
   '<b>Article 45:</b> early childhood care and education for children below 6.',
   '<b>Article 300A:</b> right to property (UDHR Art 17).',
   '<b>Article 326:</b> adult suffrage, reflecting the right to political participation (UDHR Art 21).'),
 bx('gr', '<b>Conclusion:</b> the Indian Constitution gives legal and institutional form to many UDHR principles by protecting dignity through Fundamental Rights, DPSP and Fundamental Duties.'),
 sec('STATE HUMAN RIGHTS COMMISSIONS (SHRCs)', 'r'),
 t('<b>Role</b>',
   'Working inside a State’s boundaries, SHRCs monitor prisons, handle custodial violence, review safeguards and create awareness.',
   'They are the <b>first line of institutional redress</b> for citizens and complement the NHRC in building a nationwide human rights architecture based on constitutional morality and accountability.'),
 tb(['Aspect', 'Provision (after the 2019 amendment)'],
    ['Composition', 'A Chairperson and <b>2 Members</b>. Chairperson: a retired Chief Justice or Judge of a High Court (after 2019, even a retired HC judge is eligible, not only a Chief Justice). Members: (i) a serving or retired HC judge or a District Judge with 7 years’ experience; (ii) an expert in human rights.'],
    ['Appointing authority', 'The <b>Governor</b>, on the recommendation of a committee headed by the <b>Chief Minister</b>, with the Speaker of the Assembly, the State Home Minister and the Leader of Opposition in the Assembly. If the Legislature has two Houses, the Chairman and Leader of Opposition of the Legislative Council are also included.'],
    ['Consultation', 'If a sitting HC judge or District Judge is to be appointed, <b>prior consultation with the Chief Justice of the High Court</b> is mandatory.'],
    ['Tenure', '<b>3 years or until age 70</b> (reduced from 5 years by the 2019 Amendment). Eligible for reappointment.'],
    ['Removal', 'Only the <b>President</b> can remove them (not the Governor), on grounds like insolvency, infirmity, conviction or misbehaviour, proved by a Supreme Court inquiry (similar to the NHRC).'],
    ['After tenure', 'Cannot take employment under the State or Central Government.'],
    ['Conditions of service', 'Decided by the State Government but cannot be changed to their disadvantage after appointment.'],
    ['Administration', 'The Secretary holds administrative and financial powers, subject to the Chairperson’s control (2019 amendment).']),
 t('<b>Powers and functions (Section 29 of the 1993 Act)</b> — preventive, corrective and advisory',
   '<b>1. Inquiry into violations</b> (suo motu, on petition or on a court’s direction): custodial deaths, police excesses, bonded labour, discrimination by State authorities.',
   '<b>2. Intervening in judicial proceedings</b> involving human rights allegations, so State agencies follow constitutional and legal safeguards.',
   '<b>3. Inspecting and monitoring</b> jails, detention centres and mental health institutions, and recommending humane treatment, medical care and legal aid.',
   '<b>4. Reviewing legal safeguards</b> and recommending legislative or policy changes.',
   '<b>5. Examining structural causes</b> such as terrorism, communal violence and systemic exclusion.',
   '<b>6. Engaging with international norms</b> by studying treaties and advising the State to align local laws.',
   '<b>7. Research, education and awareness</b> through drives, school curricula, workshops and tie-ups with NGOs and universities.',
   '<b>8. Collaborating with civil society</b>, acting as a bridge between NGOs and the State.'),
 t('<b>Working mechanism and inquiry procedure</b>',
   '<b>1. Complaint and admissibility.</b> Any person, NGO or public authority can complain (online, by post or in person); the Commission also takes suo motu notice of media reports. Cases <b>older than one year</b> are ordinarily not admitted unless there are exceptional circumstances.',
   '<b>2. Preliminary scrutiny (Section 17).</b> It may seek information or a report from the State Government or a subordinate authority within a set time. If there is no reply it proceeds on its own. If it is satisfied that remedial action has already been taken, it may close the matter and inform the complainant.',
   '<b>3. Inquiry and hearing.</b> It inquires directly or through its investigation division with civil-court powers under the <b>Code of Civil Procedure, 1908</b> (summoning witnesses, requisitioning documents, recording evidence on oath). Hearings are open and follow natural justice.',
   '<b>4. Recommendations (Section 18).</b> On finding a violation it may recommend <b>compensation or damages</b>, advise <b>disciplinary or criminal proceedings</b> against erring officials, and suggest policy or administrative reform. The State Government must send an <b>Action Taken Report within one month</b>.',
   '<b>5. Special procedure for armed forces (Section 19).</b> For the armed or paramilitary forces it can only call for a report from the <b>Central Government</b> and make recommendations on that basis. The Centre must report back <b>within three months</b>, so oversight exists, though limited.',
   '<b>6. Documentation and follow-up.</b> Inquiries, decisions and compliance updates are published in the Annual Report tabled in the <b>State Legislature</b>. Persistent non-compliance is publicly highlighted, which adds moral and political pressure.',
   '<b>7. Coordination and outreach.</b> It works with the NHRC, Human Rights Courts and civil society to harmonise standards and avoid duplication, with field visits and training especially in rural and tribal areas.'),
 t('<b>Key challenges</b>',
   '<b>Non-binding:</b> State governments often ignore recommendations.',
   '<b>Resource constraints:</b> staff shortages and no financial autonomy in many SHRCs.',
   '<b>Limited jurisdiction:</b> cannot revisit cases already before the NHRC, and cannot take up violations older than one year.',
   '<b>Implementation gap:</b> reports laid before legislatures often see delays or minimal follow-up.'),
 sec('HUMAN RIGHTS COURTS (SECTION 30 OF THE 1993 ACT)', 'g'),
 t('<b>Idea:</b> to give speedy justice and real enforcement, the Act requires Human Rights Courts <b>in every district</b>. They are the grassroots judicial mechanism.',
   '<b>Establishment (Section 30):</b> the State Government, with the <b>concurrence of the Chief Justice of the High Court</b>, notifies a Human Rights Court for each district to try offences from human rights violations. In most States, the <b>Sessions Court</b> is designated.',
   '<b>Jurisdiction:</b> they try human rights violations or negligence by public servants that amount to criminal offences. The aim is expeditious trial, because such cases would otherwise face delays in ordinary courts.',
   '<b>Special Public Prosecutor (Section 31):</b> the State must appoint one for every Human Rights Court; a practising advocate with at least <b>7 years’</b> experience.',
   '<b>Link with SHRC/NHRC:</b> SHRCs and the NHRC investigate and recommend; Human Rights Courts actually <b>try offences and punish</b>. This bridges the gap between recommendation and enforcement.'),
 t('<b>Limitations and recent developments</b>',
   'In practice these courts are used rarely. Many States have designated Sessions Courts only on paper, with no separate infrastructure, exclusive judges or funds. Victims are unaware, and SHRCs refer few cases.',
   'Tamil Nadu, Kerala and Maharashtra have started exclusive benches or pilot human rights courts.',
   'The Supreme Court (2018, <b>Re: Inhuman Conditions in 1382 Prisons</b>) directed States to make these courts operational to deal with custodial violence and prison abuse.'),
 ],
 recall=[('UDHR adopted on', '10 December 1948 (UN General Assembly)'), ('UDHR has how many Articles?', '30'), ('UDHR Article 21 corresponds to which Indian Article?', 'Article 326 (adult suffrage, political participation)'), ('SHRC members', 'Chairperson + 2 Members'), ('Who appoints SHRC members?', 'The Governor, on a committee led by the Chief Minister'), ('Who can remove SHRC members?', 'Only the President, after a Supreme Court inquiry'), ('SHRC and NHRC tenure after 2019', '3 years or age 70'), ('SHRC and armed forces (Section 19)', 'Can only seek a Centre report; Centre responds in 3 months'), ('Human Rights Courts under which Section?', 'Section 30 (Special Public Prosecutor: Section 31)'), ('Supreme Court case on prison conditions and HR courts', 'Re: Inhuman Conditions in 1382 Prisons, 2018')]),

dict(toc='National Commission for Women, Parivarik Mahila Lok Adalat, demand for constitutional status', id=84, title='NATIONAL COMMISSION FOR WOMEN (NCW) · COMPOSITION · POWERS · RECENT WORK · CONSTITUTIONAL STATUS · PMLA', part=0, icon='people', prio='L',
 pyq=NOPYQ + 'pp. 19-23',
 simple='The NCW is a statutory body (1992, under the NCW Act 1990) that watches over women’s rights, inquires into violations and advises the government. It has civil-court powers during inquiries but its recommendations are only advisory. There is a long-running demand to give it constitutional status like the NCSC and NCST, for autonomy, binding force and parity. The Parivarik Mahila Lok Adalat gives women a fast, informal way to settle family disputes.',
 nodes=[
 sec('WHAT THE NCW IS', 'b'),
 t('<b>Introduction</b>',
   'Set up in <b>1992</b> under the <b>National Commission for Women Act, 1990</b>. It is the apex statutory body that monitors constitutional safeguards for women, investigates violations and advises the government on legal and policy reform.',
   'It was set up to promote gender justice in line with India’s commitments under <b>CEDAW (1979)</b>.',
   'It acts as a <b>watchdog and catalyst</b> for women’s rights, empowerment and participation in governance.'),
 tb(['Aspect', 'Provision'],
    ['Composition', 'Chairperson + <b>5 Members</b> + a Member-Secretary. Chairperson: an eminent woman committed to women’s welfare. Members: experts from law, administration, management, the women’s movement or social work (<b>one from SC/ST</b>). Member-Secretary: an expert in management or research, or a senior government officer.'],
    ['Appointing authority', 'The <b>Central Government</b> appoints all members under the NCW Act, 1990.'],
    ['Tenure', '3 years (or as prescribed by the Government); eligible for reappointment.'],
    ['Resignation and removal', 'Members can resign to the Central Government; they can be removed for insolvency, conviction or incapacity.'],
    ['Service conditions', 'Set by the Central Government and not to be altered to their disadvantage during tenure.'],
    ['Headquarters', 'New Delhi; may set up regional offices as needed.']),
 sec('FUNCTIONS AND POWERS', 'r'),
 t('<b>Functions</b> (legal review, policy coordination, awareness, grievance redress)',
   '<b>1. Review of constitutional and legal safeguards:</b> checks whether constitutional provisions and laws protect women enough and recommends amendments.',
   '<b>2. Investigation and inquiry:</b> looks into specific complaints and suo motu cases of deprivation of women’s rights, non-implementation of protective laws, or failures of the administration.',
   '<b>3. Advice to government:</b> advises the Centre and States on policy, legal reform and effective implementation of women’s welfare programmes.',
   '<b>4. Monitoring custodial and institutional facilities:</b> inspects jails, remand homes and women’s shelters to ensure humane, lawful treatment.',
   '<b>5. Research and documentation:</b> studies on trafficking, workplace harassment, domestic violence and the declining sex ratio to support evidence-based policy.',
   '<b>6. Public awareness and legal literacy:</b> campaigns and workshops on women’s rights and remedies.',
   '<b>7. Collaboration with NGOs and civil society.</b>',
   '<b>8. Intervention in court cases</b> involving serious violations of women’s rights, especially where public interest is involved or legal aid is needed.'),
 t('<b>Powers (quasi-judicial: investigative, recommendatory, advisory)</b>',
   '<b>Civil-court powers</b> under the Code of Civil Procedure, 1908, while investigating: summon witnesses, examine them on oath, demand documents and receive affidavits.',
   '<b>Power to inquire</b> suo motu or on petition, including non-enforcement of protective laws and maladministration.',
   '<b>Power to call for reports</b> from any central or State department or agency on women’s rights and welfare.',
   '<b>Power to recommend prosecution, compensation or disciplinary action</b> after an inquiry.',
   '<b>Power to visit custodial institutions</b> such as jails, remand homes and shelters.',
   '<b>Power to hold public hearings</b> and consultations on issues like sexual violence, trafficking and workplace discrimination.',
   '<b>Advisory and recommendatory power:</b> recommendations are <b>not legally binding</b>, but its reports often guide reform, for example to the Dowry Prohibition Act and the Sexual Harassment at Workplace Act.'),
 sec('RECENT INTERVENTIONS (2020-2025)', 'g'),
 t('The NCW has gone beyond its statutory functions to deal with cybercrime, workplace safety, digital awareness and gender-sensitive governance, a shift from redressal to empowerment.',
   '<b>Online harassment (2020-24):</b> launched the <b>Digital Shakti Campaign</b> (Phase IV, 2022) with Meta and Cyber Peace Foundation to train women in online safety and digital literacy. Over <b>3 lakh</b> women sensitised on cyber hygiene and legal recourse.',
   '<b>Economic empowerment:</b> the <b>She Is a Changemaker</b> programme (2021) to build leadership among women in politics, PRIs and social sectors. Skill and entrepreneurship workshops for over <b>12,000</b> grassroots women leaders.',
   '<b>Legal awareness and counselling:</b> expanded the <b>One Stop Centres</b> network and strengthened the 24x7 <b>Women Helpline (181)</b> for counselling, legal aid and rehabilitation. Launched the <b>“We Think Digital”</b> campaign for cyber-legal literacy among college students.',
   '<b>High-profile cases:</b> suo motu cognisance of the <b>Hathras gang-rape (2020)</b>, <b>Manipur ethnic violence (2023)</b> and the <b>Kallakurichi school suicide case (2022)</b>, issuing notices and ensuring time-bound reporting and victim assistance.',
   '<b>Law reform:</b> recommended amendments to the Indecent Representation of Women (Prohibition) Act, pushed gender-budgeting audits and monitored implementation of POSH guidelines in workplaces.',
   '<b>Gender sensitisation:</b> with the Bureau of Police Research and Development (BPR&D) trained over <b>30,000</b> police personnel on gender sensitivity and victim handling.',
   '<b>Marginalised women:</b> initiatives for trafficking survivors, migrant women and transgender women, with health outreach and livelihood schemes (2023).'),
 sec('DEMAND FOR CONSTITUTIONAL STATUS FOR THE NCW', 'r'),
 t('<b>The idea:</b> since 1992 the NCW has been statutory. There is a consistent demand to give it constitutional status like the NCSC (Art 338) and NCST (Art 338A), to strengthen its authority and independence.',
   '<b>Why it is demanded</b>',
   '<b>Limited enforcement:</b> its recommendations are advisory, so governments and police often do not comply.',
   '<b>Executive dependence:</b> appointment and funding are controlled by the Ministry of Women and Child Development, hurting autonomy and credibility.',
   '<b>Rising gender-based violence:</b> growing crimes against women, online abuse and systemic discrimination need a stronger body with direct accountability.',
   '<b>International commitments:</b> constitutional status would match global standards such as the UN Paris Principles (1993) on independent national human rights institutions.',
   '<b>Parity:</b> SCs and STs already have constitutional commissions; similar status for women would improve institutional equality.'),
 t('<b>Expected benefits</b>',
   '<b>More autonomy:</b> independent appointments, secure tenure and money charged to the <b>Consolidated Fund of India</b>.',
   '<b>Binding recommendations</b> on women’s rights, workplace safety and law enforcement.',
   '<b>Continuity:</b> protection from political or administrative interference across governments.',
   '<b>Stronger policy impact</b> on domestic violence, cyber safety and reproductive rights.',
   '<b>Better global standing</b> in compliance with CEDAW.'),
 t('<b>Challenges the NCW faces today</b>',
   '<b>Limited autonomy and perceived political bias.</b> As a statutory body it is less independent than constitutional bodies like the EC or CAG. Allegations of bias came up during the Manipur crisis in 2023.',
   '<b>Inadequate resources.</b> A Parliamentary Committee on Empowerment of Women (2022) said staff were too few for all-India coverage.',
   '<b>High crime despite oversight.</b> NCRB 2022 recorded over <b>4.45 lakh</b> cases of crimes against women; conviction rates remain low, so deterrence is weak.',
   '<b>Marginalised women neglected.</b> Concerns of tribal, Dalit and migrant women seldom reach the NCW; women sugarcane cutters in Maharashtra stayed under-reported despite petitions.',
   '<b>Advisory nature.</b> Governments can ignore or delay action; many reports (for example after the Kathua rape case, 2018) saw slow State responses.',
   '<b>Overlapping jurisdictions</b> with State Commissions, the NHRC and Lokpal; the Committee on Empowerment of Women has repeatedly asked for a clearer delineation of powers.',
   '<b>Slow grievance redress.</b> It gets <b>20,000+</b> complaints a year (2022 data), many resolved late. There is no real-time, technology-based monitoring.'),
 t('<b>Way forward</b>',
   '<b>Constitutional status</b> for independence, as suggested by the <b>Justice Verma Committee (2013)</b> after the Delhi gang-rape.',
   '<b>Transparent, inclusive appointments</b> including women activists and academics, not only government nominees. The Supreme Court in the <b>Anjali Bhardwaj case (2019)</b> stressed transparency in appointments.',
   '<b>Reach marginalised women</b>: Dalit, tribal, migrant and rural.',
   '<b>More staff, funds and digital infrastructure</b> including tech-based grievance redress.',
   '<b>Binding power</b> to enforce key recommendations.',
   '<b>New challenges:</b> gig-economy work, cyber abuse and workplace harassment (NCW surveys in 2023 highlight gig women’s vulnerabilities).',
   '<b>Stronger collaboration</b> with civil society and State commissions.'),
 sec('PARIVARIK MAHILA LOK ADALAT (PMLA)', 'b'),
 t('Launched by the NCW with <b>State Legal Services Authorities</b> as an informal, conciliatory forum for women-related disputes, mainly family and matrimonial ones. It works under the <b>Legal Services Authorities Act, 1987</b>, aiming at speedy, friendly and low-cost justice.',
   'It handles <b>domestic violence, maintenance, divorce, dowry, property disputes and custody</b>. Proceedings are women-friendly and non-adversarial.',
   'The stress is on <b>mediation, empathy and rehabilitation</b> rather than punishment, so women can seek justice without fear or delay.',
   'It works with NGO support in resolving family disputes.'),
 ],
 recall=[('NCW established in', '1992, under the NCW Act, 1990'), ('NCW members', 'Chairperson + 5 Members + Member-Secretary'), ('Who appoints NCW members?', 'Central Government'), ('NCW tenure', '3 years'), ('Is the NCW constitutional?', 'No, statutory; there is a demand to make it constitutional'), ('Which committee suggested constitutional status (2013)?', 'Justice Verma Committee'), ('Digital Shakti Campaign was in partnership with', 'Meta and Cyber Peace Foundation'), ('Women Helpline number', '181'), ('PMLA works under which Act?', 'Legal Services Authorities Act, 1987')]),

dict(toc='NCPCR, SCPCR and Children’s Courts', id=85, title='NCPCR · STATE COMMISSIONS FOR CHILD RIGHTS (SCPCR) · CHILDREN’S COURTS', part=0, icon='people', prio='L',
 pyq=NOPYQ + 'pp. 23-30',
 simple='The NCPCR (2007, under the CPCR Act 2005) is the national watchdog for children’s rights; each State may set up a similar SCPCR, and the Act also provides Children’s Courts for speedy, child-friendly trials. It has civil-court powers and monitors the RTE, POCSO and JJ laws. Its advice is not binding, POCSO pendency is high and digital threats are growing, so reform aims at binding powers, fast-track courts and better tech.',
 nodes=[
 sec('NATIONAL COMMISSION FOR PROTECTION OF CHILD RIGHTS (NCPCR)', 'b'),
 t('<b>Introduction</b>',
   'A statutory body set up in <b>2007</b> under the <b>Commissions for Protection of Child Rights (CPCR) Act, 2005</b>. It functions under the <b>Ministry of Women and Child Development (MWCD)</b> and is the apex national institution to protect, promote and monitor children’s rights.',
   'Its moral and legal base is the <b>UN Convention on the Rights of the Child (UNCRC), 1989</b>, which India ratified in <b>1992</b>. The UNCRC defines a child as any human being <b>below 18</b>.',
   'Its mandate covers review of child-related laws, investigation of violations, monitoring of laws like the <b>RTE Act (2009), POCSO Act (2012) and JJ Act (2015)</b>, and promoting awareness and accountability.'),
 t('<b>Objectives</b>',
   '<b>Protection and redress:</b> take notice of cases where child rights are denied or violated and ensure redress by inquiry or legal action.',
   '<b>Policy and law review:</b> examine laws, policies and programmes concerning children for alignment with the Constitution and international obligations.',
   '<b>Child-centric governance:</b> integrate child-rights concerns in all government decisions and planning.',
   '<b>Monitor implementation</b> of the Right to Education, Juvenile Justice and POCSO laws.',
   '<b>Research and awareness:</b> studies, reports and outreach to make the public sensitive to child protection.',
   'In essence it is a <b>watchdog</b> that keeps the State accountable to every child’s rights to survival, development, protection and participation.'),
 t('<b>Initiatives to meet its mandate</b>',
   '<b>POCSO e-Box:</b> an online complaint box where children can directly report sexual abuse, confidentially, with quick redress and mandatory action under the POCSO Act. Used widely since 2016 so school children can complain without fear.',
   '<b>Samvardhan programme:</b> vulnerability mapping to combat child trafficking, tied to district mechanisms and anti-trafficking units. Piloted in high-trafficking districts in Bihar and West Bengal.',
   '<b>MASI App (Monitoring App for Seamless Inspection):</b> a digital tool for real-time inspection of Child Care Institutions (CCIs) to ensure compliance with JJ Act norms. It flagged serious gaps in shelter homes after the Muzaffarpur case.',
   '<b>GHAR-GO Portal (Go Home and Re-Unite):</b> a digital platform to track and help restore or repatriate children in institutional care to their families or guardians. Used during COVID-19 to restore stranded migrant children.'),
 tb(['Aspect', 'Provision'],
    ['Legal basis', 'Commissions for Protection of Child Rights Act, 2005'],
    ['Composition', '1 Chairperson + <b>6 Members</b> (at least <b>two must be women</b>)'],
    ['Chairperson', 'A person of eminence who has made outstanding contributions to child welfare and development'],
    ['Members (six fields)', 'Eminent persons experienced in: (1) education, (2) child health, care or welfare, (3) juvenile justice or child rehabilitation, (4) eliminating child labour or helping children in distress, (5) child psychology or sociology, (6) laws relating to children'],
    ['Appointing authority', 'Central Government'],
    ['Selection committee', '3 members, chaired by the Union Minister of Women and Child Development, with senior officials of the ministry and one independent expert'],
    ['Tenure', '3 years, renewable once (maximum two terms)'],
    ['Age limit', 'Chairperson up to <b>65</b>; Members up to <b>60</b>'],
    ['Removal', 'On grounds of insolvency, incapacity, moral turpitude, misuse of office, absence from three consecutive meetings, etc.'],
    ['Nature', 'Statutory, autonomous, recommendatory; has civil-court powers during inquiries']),
 sec('FUNCTIONS OF THE NCPCR', 'r'),
 t('<b>Core functions under the CPCR Act, 2005</b>',
   '<b>1. Legal and institutional review</b> of safeguards for child rights and recommending effective implementation (example: reviewing JJ Act implementation against UNCRC).',
   '<b>2. Monitoring and reporting:</b> annual and special reports to the Central Government, tabled in Parliament with an <b>Action Taken Memorandum</b>.',
   '<b>3. Inquiry and investigation</b> into violations suo motu, on complaint or on court direction. It may summon witnesses, gather evidence and recommend prosecution or remedial action.',
   '<b>4. Addressing vulnerabilities:</b> displacement, trafficking, child labour, conflict, HIV/AIDS, disasters and domestic violence.',
   '<b>5. Children in special circumstances:</b> those in conflict with law, orphans, children of prisoners and children in institutions; recommending rehabilitation.',
   '<b>6. Inspection and oversight:</b> visiting juvenile homes, observation homes and child-care institutions and directing remedial action.',
   '<b>7. Research and policy advocacy.</b>',
   '<b>8. Awareness and education</b> of the public, parents, teachers and institutions (example: Child Rights Week initiatives).',
   '<b>9. Engagement with civil society</b>: NGOs, child welfare organisations and community groups.',
   '<b>10. A limit:</b> it cannot inquire into any matter already pending before a State Commission (SCPCR) or another statutory body, to avoid overlap.'),
 t('<b>Extra functions under other child laws</b>',
   '<b>RTE Act, 2009:</b> review safeguards for the right to education; inquire into complaints of denial of free and compulsory education; use civil-court powers in such inquiries.',
   '<b>POCSO Act, 2012:</b> monitor implementation nationwide; run awareness drives and training for law enforcement and the judiciary; include POCSO work in its annual report to Parliament.',
   '<b>JJ Act, 2015:</b> oversee implementation including <b>Child Welfare Committees (CWCs)</b> and <b>Juvenile Justice Boards (JJBs)</b>; recommend improvements in rehabilitation, adoption and foster care; report compliance in its annual submission.'),
 sec('POWERS AND WORKING PROCEDURE', 'g'),
 t('<b>Inquiry process (Sections 14-17)</b>',
   '<b>1. How it takes notice:</b> suo motu, on a written complaint from an individual, NGO or child-rights organisation, or on court direction.',
   '<b>2. Calling for reports:</b> it can seek information or a report from the Central or State Government or a subordinate authority within a fixed time. If reports are delayed it can go ahead on its own; if satisfied that adequate action has been taken it may close the case and inform the complainant.',
   '<b>3. On-spot inquiry:</b> field visits, recording statements and inspecting institutions such as juvenile homes, schools or shelters.',
   '<b>4. Full investigation:</b> if a preliminary review shows a prima facie violation, it starts a full inquiry, directly or through an authorised team.'),
 t('<b>Civil-court powers (Section 14)</b>',
   'Summon and examine witnesses on oath; demand discovery and production of documents; receive evidence on affidavits; requisition public records from any court or office; issue summons for examination of persons or papers; <b>authorise search and inspection of any premises or institution housing children</b>.',
   'These give it procedural authority and independence from executive interference.'),
 t('<b>Actions after an inquiry (Sections 15-17)</b>',
   '<b>Recommend</b> that the government begin prosecution or disciplinary action, and recommend compensation, rehabilitation or damages for the victim.',
   '<b>Approach higher courts:</b> move the Supreme Court or High Court for writs, orders or directions when legal enforcement is needed.',
   '<b>Interim relief:</b> suggest rescue, shelter or medical care at once.',
   '<b>Follow-up:</b> the government must submit an Action Taken Report within a set period; the NCPCR can publish findings and monitor compliance.',
   '<b>Reports:</b> annual and special reports go to the Central and State Governments and are laid before Parliament and State Legislatures with memoranda on actions taken and reasons for non-implementation.'),
 t('<b>Working procedure</b>',
   '<b>Sittings</b> are held regularly with a minimum quorum; decisions are by majority.',
   'A <b>Secretariat and Investigation Division</b> with legal, research and field officers (on deputation or direct recruitment).',
   '<b>Coordination with SCPCRs</b> for jurisdictional clarity and information exchange.',
   '<b>Child-friendly procedure:</b> confidential hearings, anonymity of child victims and non-adversarial questioning, as per POCSO guidelines (2012).',
   '<b>Technology:</b> since 2020 online complaint portals and digital tracking through the <b>Baal Swaraj</b> e-monitoring system.'),
 t('<b>Challenges faced by the NCPCR</b>',
   '<b>Non-binding recommendations:</b> limits enforceability. The 2021 child-labour advisories were ignored by several States.',
   '<b>Judicial pendency:</b> over <b>1.6 lakh</b> POCSO cases pending, which weakens deterrence and faith in child protection.',
   '<b>Resource and staff deficit:</b> too few people to inspect child care institutions. MASI found gaps in CCIs, but follow-up is poor.',
   '<b>Perceived political influence:</b> perceived bias weakens trust in its independence; its response to the Manipur violence drew criticism for delay.',
   '<b>Online child sexual exploitation:</b> NCRB 2022 reports rising cybercrimes against children including grooming; the COVID-19 lockdown worsened online abuse and child pornography.',
   '<b>Digital trafficking networks:</b> traffickers use gaming apps and the dark web to recruit children (UNODC 2021).',
   '<b>Rural awareness gap:</b> NFHS-5 shows only <b>36%</b> of rural households know about child rights laws, so reporting is slow.'),
 t('<b>Way forward</b>',
   '<b>Binding powers:</b> amend the CPCR Act so that recommendations bind; the NHRC’s stronger powers could be a model.',
   '<b>Fast-track mechanisms:</b> special benches for POCSO and JJ Act cases (the Delhi High Court’s 2023 directive shows the need for speedier hearings).',
   '<b>AI and digital tools</b> to detect child sexual abuse material online (the EU’s INHOPE network is an example of global cooperation).',
   '<b>Cyber-safety education</b> in the NCERT curriculum (MeitY’s 2022 child-safety toolkit is a baseline).',
   '<b>More money and staff</b>, including psychologists for child care institutions.',
   '<b>Independent appointments:</b> add child-rights activists and legal experts to the selection panel (the Supreme Court’s 2019 CIC judgment stressed transparent appointments).',
   '<b>Partner with tech firms:</b> mandatory child-safety audits for gaming and social media companies (the UK Online Safety Bill 2023 offers lessons).'),
 sec('STATE COMMISSION FOR PROTECTION OF CHILD RIGHTS (SCPCR)', 'b'),
 t('Each State Government can set up an SCPCR by notification in the Official Gazette under the CPCR Act, 2005 (<b>Section 17</b>). It is the State-level counterpart of the NCPCR, giving decentralised monitoring, investigation and promotion of child rights in line with national laws and UN conventions. It ensures State laws, policies and administration match child welfare principles in the Constitution, the UNCRC and national child-protection laws.'),
 tb(['Aspect', 'Provision'],
    ['Composition', 'Chairperson + 6 Members (at least 2 women)'],
    ['Chairperson', 'A person of eminence with outstanding service in promoting child welfare and development'],
    ['Members (six fields)', 'Education; child health, welfare or development; juvenile justice or care of marginalised children; eliminating child labour; child psychology or sociology; laws relating to children'],
    ['Appointing authority', 'State Government'],
    ['Selection committee', 'Chaired by the Minister-in-charge of the department dealing with children'],
    ['Tenure', '3 years; reappointment once (maximum two terms)'],
    ['Age limit', 'Chairperson up to 65; Members up to 60'],
    ['Removal', 'Can resign to the State Government; can be removed for misbehaviour, incapacity, insolvency or abuse of office'],
    ['Nature', 'Statutory, quasi-judicial and recommendatory']),
 t('<b>Functions of the SCPCR</b> (like the NCPCR, but limited to the State)',
   'Examine State laws, welfare schemes and administrative mechanisms and recommend reform to the State Government.',
   'Inquire into violations (suo motu or on complaint) and recommend prosecution or departmental action.',
   'Inspect juvenile homes, observation homes and shelter homes run by the State or NGOs, ensuring JJ Act standards.',
   'Examine problems of children affected by communal violence, trafficking, disasters, HIV/AIDS or domestic abuse and recommend protection.',
   'Promote awareness and research on State-specific issues like dropout rates, trafficking or malnutrition.',
   'Coordinate with the NCPCR and submit reports for nationwide consistency.',
   'Advise the State on rules, policies or schemes under the RTE, JJ and POCSO Acts.'),
 t('<b>Powers and working procedure</b>',
   'Civil-court powers under the CPC, 1908: summon and examine witnesses on oath, require production of documents, receive affidavits, requisition public records, issue summons for witnesses and documents.',
   'Same inquiry mechanism as the NCPCR: receive complaints, call for government reports, do field inspections.',
   'After the inquiry it may recommend prosecution, relief to victims, or file writ petitions before the <b>State High Court or the Supreme Court</b>.',
   'It reports annually and specially to the State Government, which lays the report before the State Legislature with an action-taken memorandum; the State informs the Commission of action taken within a set time.'),
 sec('CHILDREN’S COURTS', 'r'),
 t('<b>Why:</b> to ensure speedy trials and child-friendly justice, the CPCR Act, 2005 requires <b>Children’s Courts</b> at State or district level. They deal with offences against children or violations of child rights in a way that respects the child’s age, psychology and dignity. They complement the NCPCR and SCPCRs.'),
 tb(['Aspect', 'Provision'],
    ['Legal basis', '<b>Section 25</b> of the CPCR Act, 2005'],
    ['Establishment', 'The State Government, with the <b>concurrence of the Chief Justice of the High Court</b>, may specify a Court of Session or set up a separate Children’s Court in each district'],
    ['Jurisdiction', 'To try offences against children or violations of child rights under any law (for example JJ Act, POCSO Act)'],
    ['Public Prosecutor', 'The State appoints a Public Prosecutor or Special Public Prosecutor (minimum <b>7 years</b> in criminal law)'],
    ['Objective', 'Speedy, child-sensitive justice with protection from intimidation, trauma and secondary victimisation']),
 t('<b>Functions and role</b>',
   '<b>Speedy trial</b> of child abuse, trafficking, exploitation or denial of statutory rights, in time-bound proceedings.',
   '<b>Child-friendly procedure:</b> <b>in-camera hearings</b> to protect privacy; <b>no direct cross-examination</b> of child victims; psychological support or a child counsellor; minimal exposure to the accused during testimony.',
   '<b>Enforcement:</b> offences under the POCSO Act 2012, the Juvenile Justice Act 2015 and any other law on child welfare or exploitation.',
   '<b>Coordination</b> with CWCs and JJBs for holistic rehabilitation and social reintegration after the trial.',
   '<b>Restorative orientation:</b> correction, rehabilitation and victim-centred outcomes over punishment, reflecting the <b>best interest of the child</b> principle from the UNCRC (1989).'),
 ],
 recall=[('NCPCR established in', '2007, under the CPCR Act 2005'), ('Ministry under which NCPCR works', 'Ministry of Women and Child Development'), ('NCPCR composition', '1 Chairperson + 6 Members (at least 2 women)'), ('Age limits at NCPCR', 'Chairperson 65, Members 60'), ('NCPCR tenure', '3 years, renewable once'), ('UNCRC adopted / India ratified', '1989 / 1992; child = below 18'), ('POCSO e-Box', 'Online complaint box for children'), ('MASI App', 'Monitoring App for Seamless Inspection of Child Care Institutions'), ('Children’s Courts under which Section?', 'Section 25 of the CPCR Act'), ('Pending POCSO cases mentioned', 'Over 1.6 lakh')]),

dict(toc='Minority rights in the Constitution; National Commission for Minorities', id=86, title='MINORITY RIGHTS · COMMON AND SEPARATE DOMAIN · NATIONAL COMMISSION FOR MINORITIES (NCM)', part=0, icon='flag', prio='L',
 pyq=NOPYQ + 'pp. 30-34',
 simple='The Constitution never defines “minority”, but protects them in two ways: rights that every citizen has (the common domain) and rights meant only for minorities (the separate domain, Articles 29, 30, 347, 350A and 350B). The Minorities Commission began in 1978 and became the statutory NCM in 1992. It evaluates progress, monitors safeguards, looks into complaints and recommends to governments, but only for the six notified religious communities.',
 nodes=[
 sec('CONSTITUTIONAL RIGHTS AND SAFEGUARDS FOR MINORITIES', 'b'),
 t('<b>Starting point:</b> the Constitution does <b>not define “minority”</b>, but it recognises communities based on religion or language who may need special protection to keep their identity and have equality. It gives a detailed framework of rights, which shows India’s commitment to pluralism and inclusion.',
   'These provisions divide into two domains: the <b>Common Domain</b> (rights open to all citizens, ensuring equality, liberty and justice) and the <b>Separate Domain</b> (protections meant exclusively for minorities to guard their identity, language, culture and educational institutions).',
   'This dual framework keeps equality before law universal while protecting minority identities within a secular democracy. The Preamble, which declares India a <b>secular</b> State and guarantees liberty of thought, expression, belief, faith and worship, reflects this spirit.'),
 sec('I. COMMON DOMAIN (RIGHTS OF ALL CITIZENS)', 'r'),
 t('<b>(A) Directive Principles (Part IV)</b> — not justiciable, but fundamental to governance under Article 37',
   '<b>Article 38(2):</b> the State must try to eliminate inequalities in status, facilities and opportunities among individuals and groups living in different areas or in different occupations.',
   '<b>Article 46:</b> the State must promote with special care the educational and economic interests of weaker sections, in addition to SCs and STs.',
   'Minority groups often fall within weaker sections, so these Articles give them targeted State attention.'),
 t('<b>(B) Fundamental Duties (Part IVA, Article 51A)</b>',
   'The duty to promote <b>harmony and the spirit of common brotherhood</b> among all Indians, rising above religious, linguistic, regional or sectional diversities.',
   'The duty to <b>value and preserve the rich heritage of India’s composite culture</b>.',
   'These strengthen social cohesion and mutual respect among the groups that make up the nation.'),
 tb(['Fundamental Right (Part III) in the common domain', 'What it gives'],
    ['<b>Article 14</b>', 'Equality before law and equal protection of the laws'],
    ['<b>Articles 15(1), 15(2)</b>', 'No discrimination on grounds of religion, race, caste, sex or place of birth'],
    ['<b>Article 15(4)</b>', 'State may make special provisions for socially and educationally backward classes of citizens, including minorities'],
    ['<b>Articles 16(1), 16(2)</b>', 'Equality of opportunity in public employment; no discrimination on those grounds'],
    ['<b>Article 16(4)</b>', 'Reservation in State services for backward classes not adequately represented'],
    ['<b>Article 25(1)</b>', 'Freedom of conscience and the right to freely profess, practise and propagate religion, subject to public order, morality and other Fundamental Rights'],
    ['<b>Article 26</b>', 'Every religious denomination can manage its own affairs in religion, set up and maintain institutions, and own and administer property'],
    ['<b>Article 27</b>', 'No one can be compelled to pay taxes for promoting a particular religion'],
    ['<b>Article 28</b>', 'Freedom to attend or not attend religious instruction or worship in educational institutions wholly maintained, recognised or aided by the State']),
 sec('II. SEPARATE DOMAIN (RIGHTS ONLY FOR MINORITIES)', 'g'),
 tb(['Provision', 'What it gives'],
    ['<b>Article 29(1)</b>', 'Any section of citizens with a distinct language, script or culture has the right to conserve it'],
    ['<b>Article 29(2)</b>', 'No denial of admission to any State-aided educational institution on grounds only of religion, race, caste or language'],
    ['<b>Article 30(1)</b>', 'All religious and linguistic minorities can establish and administer educational institutions of their choice'],
    ['<b>Article 30(2)</b>', 'The State cannot discriminate against minority-managed institutions when giving aid'],
    ['<b>Article 347</b>', 'The President can recognise a language spoken by a section of a State’s population for official purposes'],
    ['<b>Article 350A</b>', 'The State must provide facilities for instruction in the <b>mother tongue at the primary stage</b> for linguistic minorities'],
    ['<b>Article 350B</b>', 'A <b>Special Officer for Linguistic Minorities</b> to investigate safeguards and report to the President'],
    ['<b>Explanation I to Article 25</b>', 'Recognises the Sikh community’s right to wear and carry <b>kirpans</b> as part of freedom of religion']),
 bx('gr', '<b>India’s pluralistic vision:</b> the Constitution treats India as multi-religious, multi-lingual and multi-cultural. The framers saw the Indian nation not as a mere collection of individuals but as a <b>two-tier commonwealth</b>: of citizens, and of the cultural, religious and linguistic groups they belong to. Each group, like each citizen, has equal Fundamental Rights and equal Fundamental Duties, so diversity enriches the national identity instead of dividing it.'),
 t('<b>Protecting weaker sections in a plural society:</b> weakness can come from small numbers or from social, economic or educational disadvantage. So there are special provisions for religious and linguistic minorities, and also for SCs, STs and backward classes. This reaffirms India’s model of secularism and inclusive development, where equality goes hand in hand with diversity and every group, majority or minority, gets both protection and participation.'),
 sec('NATIONAL COMMISSION FOR MINORITIES (NCM): HISTORY', 'b'),
 tl(('1978', 'The <b>Ministry of Home Affairs Resolution</b> proposed a permanent institution. Despite many safeguards, minorities felt unequal and discriminated against; the Government said the enforcement of safeguards deserved “the highest importance”. The <b>Minorities Commission</b> was set up in 1978 under the Home Ministry.'),
    ('1984', 'Transferred to the newly created <b>Ministry of Welfare</b>, a shift from law and order to welfare and development.'),
    ('1988', 'By a Welfare Ministry Resolution, <b>linguistic minorities were excluded</b> from its jurisdiction, so the Commission looked only at religious minorities.'),
    ('1992', 'The <b>National Commission for Minorities Act, 1992</b> gave statutory status. The first statutory Commission was constituted on <b>17 May 1993</b>.'),
    ('1993 notification', 'Five religious communities notified as minorities under <b>Section 2(c)</b>: <b>Muslims, Christians, Sikhs, Buddhists and Zoroastrians (Parsis)</b>.'),
    ('2014', '<b>Jains</b> added by another notification.')),
 tb(['Religion (Census 2011)', 'Population (crore)', 'Percentage'],
    ['Muslims', '17.22', '14.2'], ['Christians', '2.78', '2.3'], ['Sikhs', '2.08', '1.7'], ['Buddhists', '0.84', '0.7'], ['Jains', '0.45', '0.4'], ['<b>Total</b>', '23.37', '19.30']),
 bx('ye', '<b>Definition under the Act:</b> Section 2(c) of the NCM Act, 1992 defines “minority” as “a community notified as such by the Central Government.” So all the Commission’s statutory functions apply only to the <b>six notified religious communities</b>.'),
 OWN('MCSBZJ', 'Notified minorities: <b>M</b>uslims, <b>C</b>hristians, <b>S</b>ikhs, <b>B</b>uddhists, <b>Z</b>oroastrians (1993) and <b>J</b>ains (2014).'),
 sec('NCM: COMPOSITION AND FUNCTIONS', 'r'),
 tb(['Parameter', 'Details'],
    ['Composition', 'Chairperson, Vice-Chairperson and <b>5 Members</b> (multi-member body)'],
    ['Eligibility', 'Persons of eminence, ability and integrity from diverse fields'],
    ['Minority representation', 'At least <b>5</b> members, including the Chairperson, must belong to the notified minority communities'],
    ['Appointing authority', 'Nominated by the Central Government (Ministry of Minority Affairs)'],
    ['Tenure', '3 years; can resign at any time; the Central Government can remove them on specified grounds'],
    ['Removal grounds', 'Insolvency, moral turpitude, unsound mind, misuse of office, absence from 3 consecutive meetings, incapacity or refusal to act']),
 t('<b>Functions (Section 9(1) of the NCM Act, 1992)</b>',
   '<b>Evaluating development progress:</b> assessing how minorities fare under Union and State programmes.',
   '<b>Monitoring safeguards:</b> overseeing implementation of constitutional and legal safeguards, including <b>Articles 29 and 30</b> on cultural and educational rights.',
   '<b>Advice and recommendations</b> to the Centre and States on better implementation and improving minorities’ condition.',
   '<b>Addressing complaints</b> of deprivation of rights and safeguards and taking them up with the relevant authorities.',
   '<b>Research and studies</b> on the causes and impact of discrimination against minorities and ways to remove it.',
   '<b>Studying socio-economic and educational conditions</b> of minority communities.',
   '<b>Policy suggestions</b> to the Union and States for minority welfare.',
   '<b>Reports:</b> periodic and special reports to the Central Government on problems minorities face.',
   '<b>Other matters</b> referred by the Central Government.'),
 t('<b>Complaints and redress</b>',
   'Common complaints: <b>police excesses or atrocities</b>, <b>service matters</b> in public employment, issues of <b>minority educational institutions</b>, and <b>encroachment or disputes over religious properties</b>.',
   'On a complaint, the NCM asks for detailed reports from the Union or State authorities, reviews the findings and recommends redress. So it acts as a statutory watchdog.'),
 ],
 recall=[('Does the Constitution define “minority”?', 'No'), ('Articles in the separate domain', '29, 30, 347, 350A, 350B (and Explanation I to Art 25)'), ('Article that lets minorities run educational institutions', 'Article 30(1)'), ('Special Officer for Linguistic Minorities', 'Article 350B'), ('Minorities Commission first set up in', '1978, under the Home Ministry'), ('Statutory NCM from', 'NCM Act 1992; first Commission 17 May 1993'), ('Who defines “minority” under the Act?', 'The Central Government, by notification (Section 2(c))'), ('Six notified minorities', 'Muslims, Christians, Sikhs, Buddhists, Zoroastrians, Jains'), ('When were Jains notified?', '2014'), ('NCM composition', 'Chairperson, Vice-Chairperson and 5 Members')]),

dict(toc='National Investigation Agency: functions, process, special courts, criticism, Ankush Vipan Kapoor (2024)', id=87, title='NATIONAL INVESTIGATION AGENCY (NIA) · FUNCTIONS · PROCESS · SPECIAL COURTS · CRITICISM · ANKUSH VIPAN KAPOOR (2024)', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 34-38',
 simple='The NIA was created by the NIA Act, 2008 after the 26/11 attacks as a central agency to investigate terrorism and other scheduled offences across India without needing State consent. Cases go to special courts and appeals lie to the High Court. Critics point to federalism worries, UAPA detentions, thin staff and low conviction in some cases. In Ankush Vipan Kapoor (2024) the Supreme Court said the NIA may also probe linked non-scheduled offences, after informing the Centre.',
 nodes=[
 sec('WHAT THE NIA IS', 'b'),
 t('<b>Introduction</b>',
   'Established through the <b>NIA Act, 2008</b>, after the <b>26/11 Mumbai terror attacks</b>, to create a specialised federal body for counter-terrorism.',
   'Headquartered in New Delhi, it can investigate <b>scheduled offences without State consent</b>, giving a swift and centralised response to terrorism, cross-border crime and offences that affect national security.',
   'It works under the <b>Ministry of Home Affairs</b> and is headed by a <b>Director General (IPS rank)</b>.'),
 tb(['Aspect', 'Details'],
    ['Legal basis', 'NIA Act, 2008; <b>amended in 2019</b> to widen its jurisdiction'],
    ['Trigger for creation', '2008 Mumbai terror attacks; the need for a federal counter-terror mechanism'],
    ['Headquarters', 'New Delhi; branch offices in Mumbai, Hyderabad, Kolkata, Guwahati, Kochi, Lucknow, Raipur and Jammu'],
    ['Leadership', 'Director General (IPS rank)'],
    ['Jurisdiction', 'Concurrent jurisdiction across India; extended <b>outside India</b> after the 2019 amendment'],
    ['Scheduled offences', 'UAPA, Explosives Act, Atomic Energy Act, WMD Act, IPC Chapter VI (waging war, sedition/offences against the State), counterfeit currency, hijacking, cyber-terrorism'],
    ['Special courts', 'Set up by the Centre or States; presided by Sessions Judges appointed in consultation with the High Court Chief Justice'],
    ['Appeals', 'Lie to the High Court; disposal targeted within 3 months']),
 sec('FUNCTIONS AND POWERS', 'r'),
 t('<b>Eight functions, with examples</b>',
   '<b>1. Counter-terror investigation across States</b> without State permission, so the anti-terror response is uniform. Example: the Pulwama attack (2019) probe led to a high conviction rate.',
   '<b>2. Jurisdiction outside India:</b> widened in 2019 to probe offences against Indians abroad. Example: Indian assets targeted in Kabul (2021) were monitored under the wider powers.',
   '<b>3. Exclusive authority on scheduled offences</b> under UAPA, the WMD Act, the Explosives Act and IPC Chapter VI. Example: a fake currency racket under IPC Sections 489A to 489E.',
   '<b>4. Concurrent jurisdiction with State police:</b> it can take over cases from State police within <b>15 days</b> of referral. Example: the Kerala gold smuggling case moved from State police in 2020.',
   '<b>5. Civil-court-like powers during inquiry:</b> summon witnesses, demand records, <b>attach property</b>. Example: asset attachment in ISIS recruitment cases under UAPA.',
   '<b>6. Specialised cells for terror financing:</b> the TFFC Cell monitors terror financing and counterfeit circulation. Example: Rs 2000 counterfeit notes traced to Pakistan-based networks.',
   '<b>7. International collaboration</b> with Interpol, FBI and Europol on global terror cases. Example: Dawood Ibrahim’s networks flagged through FATF information sharing.',
   '<b>8. Supervision through Special Courts</b> for speedy trial. Example: the Ajmer Dargah blast trial concluded in an NIA Special Court.'),
 tb(['Category', 'Acts and offences covered (scheduled offences)'],
    ['Terrorism and security', 'Unlawful Activities (Prevention) Act, 1967; Atomic Energy Act, 1962; WMD Act, 2005'],
    ['Explosives and arms', 'Explosive Substances Act, 1908; Anti-Hijacking Act, 2016; manufacture and sale of prohibited arms'],
    ['Counterfeit and smuggling', 'IPC Sections 489A-489E (counterfeit currency and notes)'],
    ['IPC Chapter VI', 'IPC Sections 121-130 (waging war, sedition, offences against the State)'],
    ['Cyber and trafficking (2019 amendment)', 'Human trafficking, cyber-terrorism, counterfeit currency, prohibited arms trade'],
    ['International dimension', 'SAARC Convention Act, 1993; offences outside India involving Indians or Indian assets']),
 sec('HOW THE NIA WORKS (PROCESS)', 'g'),
 t('<b>Eight steps</b>',
   '<b>1. Initial reporting:</b> local police send the FIR to the State and then to the Centre within <b>24 hours</b>.',
   '<b>2. Central screening within 15 days:</b> the Centre decides whether it is a scheduled offence fit for the NIA. Example: the 2022 Ludhiana blast was quickly handed over.',
   '<b>3. Transfer from State:</b> once the NIA takes over, State police stop all investigation. Example: the West Bengal coal scam probe moved from CID to NIA.',
   '<b>4. Preliminary inquiry and registration:</b> the DG approves the FIR and an inquiry wing begins fact-finding.',
   '<b>5. Investigation with nationwide powers:</b> NIA officers act as station house officers across India. Example: nationwide raids against the PFI in September 2022.',
   '<b>6. Trial in Special Courts:</b> before Sessions Judges appointed on the High Court Chief Justice’s recommendation. Example: the Samjhauta Express blast case in Panchkula.',
   '<b>7. Appeals to the High Court within 30 days:</b> a two-judge bench is required to dispose of them within three months.',
   '<b>8. State coordination during trial:</b> States must give cooperation, logistics and witnesses.'),
 t('<b>Special Courts under the NIA Act</b>',
   'Notified by the <b>Central Government</b> to try only scheduled offences investigated by the agency.',
   'Presided over by a <b>Sessions Judge or Additional Sessions Judge</b> nominated by the Chief Justice of the High Court.',
   'They can sit outside their normal seat if needed, which gives flexibility for sensitive trials.',
   'Appeals go <b>directly to the High Court</b>; timelines are stressed to avoid delays in terror trials.'),
 sec('CHALLENGES AND CRITICISMS', 'r'),
 t('<b>Eight criticisms</b>',
   '<b>Federalism:</b> States say the Centre overrides their policing powers. The Kerala CM criticised the NIA takeover of the gold smuggling case.',
   '<b>Human rights:</b> allegations of coercive interrogation and prolonged detention under UAPA. Amnesty International flagged arrests after the Bhima Koregaon case.',
   '<b>Manpower:</b> only about <b>1,200</b> personnel against a rising caseload of 300+ cases a year. A CAG report (2021) flagged staff shortage in regional offices.',
   '<b>Overreach and misuse:</b> perceived selective targeting of NGOs and minority-linked groups; Greenpeace India flagged misuse of foreign-funding scrutiny.',
   '<b>Low convictions in some high-profile cases:</b> the Samjhauta Express blast verdict acquitted all accused (2019), which weakens deterrence and credibility.',
   '<b>Technology lag:</b> no AI-driven monitoring of the dark net and encrypted networks; Europol reports highlight India’s vulnerability to cyber-radicalisation.',
   '<b>Coordination gaps with State agencies:</b> delayed intelligence sharing reduces efficiency (the 2016 Pathankot attack probe saw jurisdictional disputes).',
   '<b>Perceived political bias:</b> criticism that NIA cases often match the ruling party’s narrative; opposition flagged selective raids against NGOs in 2021.'),
 t('<b>Way forward</b>',
   '<b>Federal cooperation:</b> a Centre-State coordination council for security issues, on the Inter-State Council model.',
   '<b>More staff and regional presence:</b> recruitment and new offices in the North-East and border regions (a 2022 parliamentary panel recommended more branch offices).',
   '<b>Digital and cyber capability:</b> AI, blockchain and forensic tools for dark-net monitoring (lessons from the US FBI’s Joint Terrorism Task Force).',
   '<b>Human rights compliance:</b> NHRC oversight in custodial interrogation and trials; UN guidelines on counter-terror measures.',
   '<b>Efficient special courts:</b> digital courts for faster terror trials (e-Courts Phase III, 2023).',
   '<b>Accountability and audits:</b> annual CAG audit of the NIA for budget and impartiality.',
   '<b>Global cooperation:</b> stronger MLATs and Interpol red notices for fugitives abroad (cooperation with the UAE sped up extradition of gangsters).',
   '<b>Awareness and citizen participation:</b> reporting channels, helplines and civic awareness.'),
 sec('SUPREME COURT: ANKUSH VIPAN KAPOOR v. NIA (2024)', 'b'),
 t('The Supreme Court widened the scope of NIA investigation by reading <b>Section 8 of the NIA Act</b> holistically.',
   '<b>1. Linked offences:</b> the NIA may investigate <b>non-scheduled offences connected with a scheduled offence</b>. Example: if terror financing involves IPC fraud charges, the NIA can probe both.',
   '<b>2. Central approval:</b> the agency must <b>inform the Central Government before widening the investigation</b>. This gives executive oversight and prevents arbitrary extension of powers.',
   '<b>3. Joint investigation:</b> linked offences must be investigated together with the scheduled offence, to avoid duplication, keep consistency and strengthen prosecution.',
   '<b>4. Significance:</b> the ruling widens the NIA’s jurisdiction and reinforces India’s anti-terror architecture. It helps tackle <b>hybrid crimes</b> where terror links overlap with economic and cyber offences.'),
 bx('gr', '<b>Conclusion:</b> the NIA is India’s federal answer to terrorism and national security threats. Its wide jurisdiction and international reach make it indispensable, but federal friction, resource gaps and digital challenges need fixing. With transparency, modern technology and Centre-State synergy it can become a global-standard counter-terror agency.'),
 ],
 recall=[('NIA created by which Act and when?', 'NIA Act, 2008, after the 26/11 attacks'), ('Which year did the Act widen NIA jurisdiction?', '2019 (including offences outside India)'), ('NIA is headed by', 'Director General (IPS rank)'), ('Ministry under which NIA works', 'Ministry of Home Affairs'), ('Centre screens a case within', '15 days'), ('Special Court judges are', 'Sessions Judges appointed in consultation with the High Court Chief Justice'), ('Appeals from NIA Special Courts go to', 'The High Court (two-judge bench; 3 months)'), ('Case that widened NIA scope in 2024', 'Ankush Vipan Kapoor v. NIA'), ('What did that case allow?', 'Probing linked non-scheduled offences, after informing the Centre'), ('Staff mentioned in the handout', 'About 1,200 personnel vs 300+ cases a year')]),
]
